private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null || end < 0 || end >= headerPart.length()) {
        return -1;
    }
    int len = headerPart.length();
    for (int i = end; i < len - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    // If we reach here, the line terminator was not found
    return -1;
}

