    if (headerPart == null || end < 0 || end >= headerPart.length()) {
        return -1;
    }
    int len = headerPart.length();
    // Scan for CRLF sequence starting from the provided index.
    for (int i = end; i < len - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            // Return the index of the carriage return which starts the line terminator.
            return i;
        }
    }
    // No line terminator found.
    return -1;
}

