@Override public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    try {
        // create left partition vertices
        List<V> left = new ArrayList<>();
        for (int i = 0; i < 2; i++) { // left side size 2
            @SuppressWarnings("unchecked")
            V vertex = (V) new Object();
            target.addVertex(vertex);
            left.add(vertex);
            resultMap.put("L" + i, vertex);
        }
        // create right partition vertices
        List<V> right = new ArrayList<>();
        for (int j = 0; j < 3; j++) { // right side size 3
            @SuppressWarnings("unchecked")
            V vertex = (V) new Object();
            target.addVertex(vertex);
            right.add(vertex);
            resultMap.put("R" + j, vertex);
        }
        // add all possible edges between left and right partitions
        for (V u : left) {
            for (V v : right) {
                @SuppressWarnings("unchecked")
                E edge = (E) new Object();
                target.addEdge(u, v, edge);
            }
        }
    } catch (Exception e) {
        // Handle possible runtime exceptions during graph construction
        e.printStackTrace();
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null) {
        throw new IllegalArgumentException("Target graph cannot be null.");
    }
    if (resultMap == null || resultMap.isEmpty()) {
        throw new IllegalArgumentException("Result map must contain at least one vertex.");
    }
    try {
        // Map partition names to list of vertices in that partition
        Map<String, List<V>> partitionMap = new HashMap<>();
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            String partition = entry.getKey();
            V vertex = entry.getValue();
            if (vertex == null) continue;
            partitionMap.computeIfAbsent(partition, k -> new ArrayList<>()).add(vertex);
        }
        // Add all vertices to target graph
        for (List<V> vertices : partitionMap.values()) {
            for (V v : vertices) {
                target.addVertex(v);
            }
        }
        // If less than two partitions, nothing to connect
        if (partitionMap.keySet().size() < 2) {
            return;
        }
        // Get the first two partitions
        Iterator<List<V>> iter = partitionMap.values().iterator();
        List<V> left = iter.next();
        List<V> right = iter.next();
        // Connect every vertex in left to every vertex in right
        for (V u : left) {
            for (V w : right) {
                target.addEdge(u, w);
            }
        }
    } catch (Exception e) {
        // Log the exception or rethrow as unchecked if appropriate
        throw new RuntimeException("Failed to construct complete bipartite graph", e);
    }
}

@Override public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    if(target == null || resultMap == null) return;
    List<V> vertices = new ArrayList<>(resultMap.values());
    int total = vertices.size();
    if(total < 2) return;
    int mid = total / 2;
    for(int i = 0; i < mid; i++){
        V u = vertices.get(i);
        for(int j = mid; j < total; j++){
            V v = vertices.get(j);
            try{
                target.addEdge(u, v);
            }catch(Exception e){
                // ignore if edge already exists or other issue
            }
        }
    }
}

