public static <T>int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) throw new IllegalArgumentException("OutputStream is null");
    if (schema == null) throw new IllegalArgumentException("Schema is null");
    int size = schema.getSerializedSize(message);
    if (buffer == null) buffer = LinkedBuffer.allocate();
    CodedOutputStream cos = CodedOutputStream.newInstance(buffer, size);
    schema.writeTo(cos, message);
    cos.flush();
    // write length prefix (varint32)
    int temp = size;
    while ((temp & ~0x7F) != 0) {
        out.write((temp & 0x7F) | 0x80);
        temp >>>= 7;
    }
