    Class<?>[] result = new Class<?>[typeArgs.length];

    // Build a map from TypeVariable to actual Class<?> based on targetType's generic superclass and interfaces
    java.util.Map<TypeVariable<?>, Class<?>> typeVarMap = new java.util.HashMap<>();

    // Process generic superclass
