    if (genericSuper instanceof ParameterizedType) {
        ParameterizedType superPT = (ParameterizedType) genericSuper;
        Type[] superArgs = superPT.getActualTypeArguments();
        TypeVariable<?>[] superParams = ((Class<?>) superPT.getRawType()).getTypeParameters();
        for (int i = 0; i < superParams.length && i < superArgs.length; i++) {
            if (superArgs[i] instanceof Class<?>) {
                typeVarMap.put(superParams[i], (Class<?>) superArgs[i]);
            }
        }
    }

    // Process generic interfaces
    for (Type iface : targetType.getGenericInterfaces()) {
        if (iface instanceof ParameterizedType) {
            ParameterizedType ifacePT = (ParameterizedType) iface;
            Type[] ifaceArgs = ifacePT.getActualTypeArguments();
            TypeVariable<?>[] ifaceParams = ((Class<?>) ifacePT.getRawType()).getTypeParameters();
            for (int i = 0; i < ifaceParams.length && i < ifaceArgs.length; i++) {
                if (ifaceArgs[i] instanceof Class<?>) {
                    typeVarMap.put(ifaceParams[i], (Class<?>) ifaceArgs[i]);
                }
            }
        }
    }

    // Resolve each type argument to a raw Class
    for (int i = 0; i < typeArgs.length; i++) {
        Type t = typeArgs[i];
        Class<?> resolved = null;
        if (t instanceof Class<?>) {
            resolved = (Class<?>) t;
        } else if (t instanceof ParameterizedType) {
            Type raw = ((ParameterizedType) t).getRawType();
            if (raw instanceof Class<?>) {
                resolved = (Class<?>) raw;
            }
        } else if (t instanceof GenericArrayType) {
            // Try to determine the component type
            Type comp = ((GenericArrayType) t).getGenericComponentType();
            if (comp instanceof Class<?>) {
                try {
                    resolved = java.lang.reflect.Array.newInstance((Class<?>) comp, 0).getClass();
                } catch (Exception e) {
                    return null;
                }
            }
        } else if (t instanceof TypeVariable) {
            resolved = typeVarMap.get(t);
        }
        if (resolved == null) {
            return null;
        }
        result[i] = resolved;
    }
    return result;
}

