    List<TimeRange> result = new ArrayList<>();
    if (start >= end) {
        return result;
    }
    long maxDuration = FETCH_DATA_DURATION;
    if (maxDuration <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }
    for (long s = start; s < end; ) {
        long e = Math.min(s + maxDuration, end);
        result.add(new TimeRange(s, e));
        s = e;
    }
    return result;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    // Validate inputs
    if (start > end) {
        throw new IllegalArgumentException("Start time must be less than or equal to end time.");
    }
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalStateException("FETCH_DATA_DURATION must be a positive value.");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while (current < end) {
        long segEnd = current + FETCH_DATA_DURATION;
        if (segEnd > end) {
            segEnd = end;
        }
        ranges.add(new TimeRange(current, segEnd));
        current = segEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start,long end){
    if (start > end) {
