static long compressTimeBucket(long timeBucket,int dayStep){
    if (timeBucket <= 0 || dayStep <= 0) {
        return timeBucket;
    }
    try {
        int year = (int)(timeBucket / 10000);
        int month = (int)((timeBucket % 10000) / 100);
        int day = (int)(timeBucket % 100);
        int bucketIndex = (day - 1) / dayStep;
        int baseDay = bucketIndex * dayStep + 1;
        // Simple overflow safeguard: ensure baseDay not greater than 31
        if (baseDay > 31) {
            baseDay = 1;
        }
        return year * 10000L + month * 100L + baseDay;
    } catch (Exception e) {
        return timeBucket;
    }
}

