    int year = (int) (timeBucket / 10000L);
    int month = (int) ((timeBucket / 100L) % 100L);
    int day = (int) (timeBucket % 100L);

    int newDay = ((day - 1) / dayStep) * dayStep + 1;

    // Recombine into a long of the form yyyymmdd
    return year * 10000L + month * 100L + newDay;
}

