    if (str == null || index < 0 || len < 0 || (long) index + len > str.length()) {
        return 0;
    }
    int size = 0;
    int i = index;
    int end = index + len;
    while (i < end) {
        char ch = str.charAt(i);
        int codePoint;
        if (Character.isHighSurrogate(ch) && i + 1 < end) {
            char next = str.charAt(i + 1);
            if (Character.isLowSurrogate(next)) {
                codePoint = Character.toCodePoint(ch, next);
                i += 2;
            } else {
                codePoint = ch;
                i++;
            }
        } else {
            codePoint = ch;
            i++;
        }
        if (codePoint <= 0x7F) {
            size += 1;
        } else if (codePoint <= 0x7FF) {
            size += 2;
        } else if (codePoint <= 0xFFFF) {
            size += 3;
        } else {
            size += 4;
        }
    }
    return size;
}

