    while (true) {
        int b = in.read();
        if (b == -1) {
            throw new EOFException();
        }
        result |= (long)(b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            break;
        }
        shift += 7;
        if (shift >= 64) {
            throw new IOException("Varint too long");
        }
    }
    return result;
}

