private void pop(final String descriptor){
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor cannot be null");
    }
    int slotsToPop = 0;
    int len = descriptor.length();
    int i = 0;
    try {
        if (len > 0 && descriptor.charAt(0) == '(') {
            // method descriptor: parse argument types until ')'
            i = 1;
            while (i < len && descriptor.charAt(i) != ')') {
                // skip array brackets
                while (i < len && descriptor.charAt(i) == '[') {
                    i++;
                }
                char c = descriptor.charAt(i);
                if (c == 'L') {
                    // reference type: consume until ';'
                    i = descriptor.indexOf(';', i);
                    if (i == -1) {
                        throw new IllegalArgumentException("invalid descriptor");
                    }
                    i++; // skip ';'
                    slotsToPop += 1;
                } else {
                    // primitive type
                    if (c == 'J' || c == 'D') {
                        slotsToPop += 2;
                    } else {
                        slotsToPop += 1;
                    }
                    i++; // consume the type char
                }
            }
            if (i >= len) {
                throw new IllegalArgumentException("invalid method descriptor");
            }
            // skip the closing ')'
            i++;
            // skip return type descriptor (if any, but it is not popped)
        } else {
            // single type descriptor
            while (i < len && descriptor.charAt(i) == '[') {
                i++;
            }
            char c = descriptor.charAt(i);
            if (c == 'L') {
                i = descriptor.indexOf(';', i);
                if (i == -1) {
                    throw new IllegalArgumentException("invalid descriptor");
                }
                i++; // skip ';'
                slotsToPop += 1;
            } else {
                if (c == 'J' || c == 'D') {
                    slotsToPop += 2;
                } else {
                    slotsToPop += 1;
                }
                i++; // consume the type char
            }
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("invalid descriptor", e);
    }
    if (pos < slotsToPop) {
        throw new IllegalStateException("stack underflow");
    }
    pos -= slotsToPop;
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    int start = 0;
    int end = descriptor.length();
    int index = descriptor.indexOf('(');
    if (index != -1) {
        start = index + 1;
        int close = descriptor.indexOf(')', start);
        if (close != -1) {
            end = close;
        }
    }
    int i = start;
    while (i < end) {
        char c = descriptor.charAt(i);
        if (c == '[') {
            while (i < end && descriptor.charAt(i) == '[') {
                i++;
            }
            if (i >= end) {
                break;
            }
            c = descriptor.charAt(i);
        }
        if (c == 'L') {
            int semicolon = descriptor.indexOf(';', i);
            if (semicolon == -1) {
                break;
            }
            i = semicolon;
            pos--; // pop one object or interface type
        } else {
            if (c == 'J' || c == 'D') {
                pos -= 2; // long or double occupies two stack slots
            } else {
                pos--; // primitive type
            }
        }
        i++;
    }
}

