private void pop(final String descriptor){
    int p = 0;
    final int len = descriptor.length();
    while (p < len) {
        char c = descriptor.charAt(p);
        if (c == '(') {  // method descriptor
            p++; // skip '('
            while (p < len && descriptor.charAt(p) != ')') {
                char t = descriptor.charAt(p);
                switch (t) {
                    case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                        pos--;
                        p++;
                        break;
                    case 'J': case 'D':
                        pos -= 2;
                        p++;
                        break;
                    case 'L':
                        pos--;
                        int end = descriptor.indexOf(';', p);
                        if (end == -1) throw new IllegalArgumentException("Invalid descriptor");
                        p = end + 1;
                        break;
                    case '[':
                        pos--;
                        int arrayEnd = p + 1;
                        if (arrayEnd < len) {
                            if (descriptor.charAt(arrayEnd) == 'L') {
                                arrayEnd = descriptor.indexOf(';', arrayEnd);
                                if (arrayEnd == -1) throw new IllegalArgumentException("Invalid descriptor");
                                p = arrayEnd + 1;
                            } else {
                                p = arrayEnd + 1;
                            }
                        } else {
                            p = arrayEnd;
                        }
                        break;
                    default:
                        p++;
                        break;
                }
            }
            if (p < len && descriptor.charAt(p) == ')') p++;
        } else { // single type descriptor
            char t = descriptor.charAt(p);
            switch (t) {
                case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
                    pos--;
                    p++;
                    break;
                case 'J': case 'D':
                    pos -= 2;
                    p++;
                    break;
                case 'L':
                    pos--;
                    int end = descriptor.indexOf(';', p);
                    if (end == -1) throw new IllegalArgumentException("Invalid descriptor");
                    p = end + 1;
                    break;
                case '[':
                    pos--;
                    int arrayEnd = p + 1;
                    if (arrayEnd < len) {
                        if (descriptor.charAt(arrayEnd) == 'L') {
                            arrayEnd = descriptor.indexOf(';', arrayEnd);
                            if (arrayEnd == -1) throw new IllegalArgumentException("Invalid descriptor");
                            p = arrayEnd + 1;
                        } else {
                            p = arrayEnd + 1;
                        }
                    } else {
                        p = arrayEnd;
                    }
                    break;
                default:
                    p++;
                    break;
            }
        }
    }
}

@Override public void write(final byte b[],final int off,final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("buffer is null");
    }
    if (off < 0 || len < 0 || off + len > b.length) {
        throw new IndexOutOfBoundsException("off "+off+" len "+len+" exceeds buffer length "+b.length);
    }
    int newCount = count + len;
    if (newCount > buf.length) {
        grow(newCount);
    }
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

@Override public void write(final byte b[], final int off, final int len) throws IOException {
    if (b == null) {
        throw new NullPointerException("Null array");
    }
    if ((off < 0) || (off > b.length) || (len < 0) || ((off + len) > b.length)) {
        throw new IndexOutOfBoundsException("Offset or length out of bounds");
    }
    ensureCapacity(count + len);
    System.arraycopy(b, off, buf, count, len);
    count += len;
}

