public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    Tuple2D lower = box.getLowerBound();
    Tuple2D upper = box.getUpperBound();
    double midX = (lower.getX() + upper.getX()) / 2.0;
    Box2D left = new Box2D(lower, new Tuple2D(midX, upper.getY()));
    Box2D right = new Box2D(new Tuple2D(midX, lower.getY()), upper);
    return Pair.of(left, right);
}

public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null){
        throw new IllegalArgumentException("box cannot be null");
    }
    double totalWidth = box.getWidth();
    double halfWidth = totalWidth / 2.0;
    double rightWidth = totalWidth - halfWidth;

    Box2D leftBox = new Box2D(
            box.getX(),
            box.getY(),
            halfWidth,
            box.getHeight());
    Box2D rightBox = new Box2D(
            box.getX() + halfWidth,
            box.getY(),
            rightWidth,
            box.getHeight());
    return new Pair<>(leftBox, rightBox);
}

