        double maxY = box.getMaxY();
        double centerX = (minX + maxX) / 2.0;
        Box2D left = new Box2D(minX, centerX, minY, maxY);
        Box2D right = new Box2D(centerX, maxX, minY, maxY);
        return Pair.of(left, right);
    } catch (Exception e) {
        throw new RuntimeException("Failed to split box along X axis", e);
    }
}

