public static String capitalize(String name){
    if (name == null) {
        return null;
    }
    int len = name.length();
    if (len == 0) {
        return name;
    }
    // If the first two characters are both uppercase, leave the string unchanged 
    // (this is the inverse of Introspector.decapitalize behavior).
    if (len > 1 && Character.isUpperCase(name.charAt(0)) && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    char first = name.charAt(0);
    char capitalizedFirst = Character.toUpperCase(first);
    if (first == capitalizedFirst) {
        return name;
    }
    return capitalizedFirst + name.substring(1);
}

