public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) return 0;
    int totalSize = 0;
    try {
        // Try to obtain the size of the buffer
        try {
            java.lang.reflect.Method sizeMethod = node.getClass().getMethod("getSize");
            Object sizeObj = sizeMethod.invoke(node);
            if (sizeObj instanceof Integer) {
                totalSize = ((Integer) sizeObj).intValue();
            }
        } catch (NoSuchMethodException ignored) {
            try {
                java.lang.reflect.Field sizeField = node.getClass().getDeclaredField("_size");
                sizeField.setAccessible(true);
                Object sizeObj = sizeField.get(node);
                if (sizeObj instanceof Integer) {
                    totalSize = ((Integer) sizeObj).intValue();
                }
            } catch (Exception ignored) {}
        }

        // Locate the head node of the linked list
        Object current = null;
        try {
            java.lang.reflect.Field headField = node.getClass().getDeclaredField("head");
            headField.setAccessible(true);
            current = headField.get(node);
        } catch (NoSuchFieldException e1) {
            try {
                java.lang.reflect.Field headField = node.getClass().getDeclaredField("_head");
                headField.setAccessible(true);
                current = headField.get(node);
            } catch (Exception ignored) {}
        }

        // Iterate through the linked nodes and write bytes to the DataOutput
        while (current != null) {
            Class<?> nodeCls = current.getClass();

            // Retrieve byte array
            Object arrayObj = null;
            try {
                java.lang.reflect.Field arrayField = nodeCls.getDeclaredField("array");
                arrayField.setAccessible(true);
                arrayObj = arrayField.get(current);
            } catch (Exception ignored) {}

            if (!(arrayObj instanceof byte[])) {
                break;
            }
            byte[] arr = (byte[]) arrayObj;

            // Retrieve start and end indices
            int start = 0;
            int end = arr.length;
            try {
                java.lang.reflect.Field startField = nodeCls.getDeclaredField("start");
                startField.setAccessible(true);
                Object startVal = startField.get(current);
                if (startVal instanceof Integer) start = ((Integer) startVal).intValue();
            } catch (Exception ignored) {}
            try {
                java.lang.reflect.Field endField = nodeCls.getDeclaredField("end");
                endField.setAccessible(true);
                Object endVal = endField.get(current);
                if (endVal instanceof Integer) end = ((Integer) endVal).intValue();
            } catch (Exception ignored) {}

            int len = end - start;
            if (len > 0) {
                out.write(arr, start, len);
            }

            // Move to next node
            try {
                java.lang.reflect.Field nextField = nodeCls.getDeclaredField("next");
                nextField.setAccessible(true);
                current = nextField.get(current);
            } catch (Exception ignored) {
                break;
            }
        }

        // Reset the buffer for reuse
        try {
            java.lang.reflect.Method resetMethod = node.getClass().getMethod("reset");
            resetMethod.invoke(node);
        } catch (Exception ignored) {}
    } catch (Exception e) {
        // Ignore any reflection failures, return size discovered (or 0)
    }
    return totalSize;
}

