        if (tag == 7) {          // OBJECT
            stackMapTableEntries.putShort(type.getConstantPoolIndex());
        } else if (tag == 8) {   // UNINITIALIZED
            stackMapTableEntries.putShort(type.getOffset());
        }
    }
}

private void putAbstractTypes(final int start,final int end){
    if (currentFrame == null || stackMapTableEntries == null){
        throw new IllegalStateException("currentFrame or stackMapTableEntries not initialized");
    }
    final int frameSize = currentFrame.size();
    if (start < 0 || end > frameSize || start > end){
        throw new IllegalArgumentException("Invalid start/end indices: start=" + start + ", end=" + end + ", frameSize=" + frameSize);
    }
    try{
        for (int i = start; i < end; i++){
            Object type = currentFrame.get(i);
            int typeCode = getVerificationTypeCode(type);
            stackMapTableEntries.write(typeCode);
            if (isObjectType(typeCode) || isUninitializedType(typeCode)){
                byte[] info = getTypeInfo(type);
                stackMapTableEntries.write(info);
            }
        }
    }catch(IOException e){
        throw new RuntimeException("Failed to write abstract types to stackMapTableEntries", e);
    }
}

private void putAbstractTypes(final int start,final int end){
    for(int i=start;i<end;i++){
        stackMapTableEntries.put((byte) currentFrame[i]);
    }
}

private void putAbstractTypes(final int start, final int end) {
    // Ensure the supplied range is valid
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IndexOutOfBoundsException("Invalid start or end indices for currentFrame");
    }

    // Iterate over the requested slice of the current frame and emit the
    // JVMS verification_type_info representation for each element.
    for (int i = start; i < end; i++) {
        AbstractType type = currentFrame[i];

        // Each abstract type knows how to write itself into the stack map table.
        // Most types require only a single byte (the tag); OBJECT and UNINITIALIZED
        // types additionally require two-byte information (cp index or offset).
        byte tag = type.getVerificationTag();
        stackMapTableEntries.add(tag);

        switch (tag) {
            case VerificationTypeInfo.ITEM_OBJECT:
                // For OBJECT type: write a two‑byte constant‑pool index.
                stackMapTableEntries.addShort(type.getObjectCpIndex());
                break;

            case VerificationTypeInfo.ITEM_UNINITIALIZED:
                // For UNINITIALIZED type: write a two‑byte offset.
                stackMapTableEntries.addShort(type.getOffset());
                break;

            default:
                // All other tags are fully represented by the single tag byte.
                break;
        }
    }
}

