@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Only handle conversion to Character or char
    if (!Character.class.isAssignableFrom(type) && type != char.class) {
        // Not a character target type; return the value unchanged
        return value;
    }

    if (value == null) {
        return null;
    }

    // If already a Character, just return it
    if (value instanceof Character) {
        return value;
    }

    // Handle Character via CharSequence (String, StringBuilder, etc.)
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() > 0) {
            return cs.charAt(0);
        } else {
            throw new Exception("Cannot convert empty CharSequence to Character");
        }
    }

    // Handle numeric values: convert the integer value to a character code
    if (value instanceof Number) {
        int intValue = ((Number) value).intValue();
        return (char) intValue;
    }

    // For String specifically (redundant with CharSequence handling but explicit)
    if (value instanceof String) {
        String str = (String) value;
        if (!str.isEmpty()) {
            return str.charAt(0);
        } else {
            throw new Exception("Cannot convert empty String to Character");
        }
    }

    // Fallback: use toString() and take first character if available
    String str = value.toString();
    if (!str.isEmpty()) {
        return str.charAt(0);
    }

    // If all above failed, throw exception
    throw new Exception("Conversion to Character failed for value: " + value);
}

@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (!Character.class.equals(type)) {
        throw new IllegalArgumentException("Unsupported target type: " + type);
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() == 1) {
            return str.charAt(0);
        } else {
            throw new IllegalArgumentException("Cannot convert String to Character: length is not 1");
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal >= 0 && intVal <= 65535) { // unicode range
            return (char) intVal;
        } else {
            throw new IllegalArgumentException("Number value out of Character range");
        }
    }
    // Fallback: try to use string representation
    String valStr = value.toString();
    if (valStr.length() == 1) {
        return valStr.charAt(0);
    }
    throw new IllegalArgumentException("Cannot convert value to Character: " + value);
}

