public static int nextPrime(int desiredCapacity){
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity must be non-negative");
    }
    final int[] PRIMES = {
        3, 7, 13, 23, 43, 79, 163, 331, 673, 1361,
        2729, 5471, 10949, 21911, 43853, 87719, 175447, 350899, 701819, 1403641,
        2807303, 5614657, 11229331, 22458671, 44917381, 89834771, 179669551,
        359339171, 718678363, 1437356723, 2147483647
    };
    int index = java.util.Arrays.binarySearch(PRIMES, desiredCapacity);
    if (index < 0) {
        index = -index - 1;
    }
    if (index >= PRIMES.length) {
        index = PRIMES.length - 1;
    }
    return PRIMES[index];
}

public static int nextPrime(int desiredCapacity) {
    // Ensure a non-negative capacity value. Small table sizes resolve to the first prime.
    if (desiredCapacity <= 2) {
        return 2;
    }

    // Start at the desired capacity, but force it to be odd
    int candidate = (desiredCapacity & 0x1) == 0 ? desiredCapacity + 1 : desiredCapacity;

    // For large capacities, we still bound the search to within 11% if desiredCapacity >= 1000
    int maxCandidate = (desiredCapacity >= 1000)
            ? (int) Math.ceil(desiredCapacity * 1.11)
            : Integer.MAX_VALUE;

    while (candidate <= maxCandidate) {
        if (isPrime(candidate)) {
            return candidate;
        }
        // Skip even numbers: only odd candidates need checking
        candidate += 2;
    }

    // In the unlikely event we couldn't find a prime within the 11% window, keep searching.
    while (true) {
        if (isPrime(candidate)) {
            return candidate;
        }
        candidate += 2;
        // Avoid overflow
        if (candidate <= 0) {
            return Integer.MAX_VALUE;
        }
    }
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 3) {
        return 3;
    }
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    while (!isPrime(candidate)) {
        candidate += 2;
    }
    return candidate;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 2) {
        return 2;
    }
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // Make odd
    }
    int upperBound = Integer.MAX_VALUE;
    if (desiredCapacity >= 1000) {
        upperBound = desiredCapacity + desiredCapacity / 10 + 1; // within ~11%
    }
    while (candidate <= upperBound) {
        boolean prime = true;
        int limit = (int) Math.sqrt(candidate);
        for (int i = 3; i <= limit; i += 2) {
            if (candidate % i == 0) {
                prime = false;
                break;
            }
        }
        if (prime) {
            return candidate;
        }
        candidate += 2; // next odd number
    }
    // Fallback if not found within bound: search further:
    while (true) {
        boolean prime = true;
        int limit = (int) Math.sqrt(candidate);
        for (int i = 3; i <= limit; i += 2) {
            if (candidate % i == 0) {
                prime = false;
                break;
            }
        }
        if (prime) {
            return candidate;
        }
        candidate += 2;
    }
}

public static int nextPrime(int desiredCapacity){
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Ensure candidate is odd (except 2)
    int candidate = (desiredCapacity % 2 == 0) ? desiredCapacity + 1 : desiredCapacity;
    // Handle corner case if starting from 3 or higher
    if (candidate < 3) {
        candidate = 3;
    }
    while (true) {
        // Quickly eliminate multiples of 3 and 5
        if (candidate > 3 && (candidate % 3 == 0 || candidate % 5 == 0)) {
            // Skip to next odd number
            candidate += 2;
            continue;
        }
        // compute up to sqrt(candidate)
        int sqrt = (int) Math.sqrt(candidate);
        boolean isPrime = true;
        // check divisibility by odd numbers only
        for (int i = 3; i <= sqrt; i += 2) {
            if (candidate % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (isPrime) {
            return candidate;
        }
        // Move to next odd number; guard against overflow
        if (candidate > Integer.MAX_VALUE - 2) {
            throw new RuntimeException("Unable to find a prime within int range");
        }
        candidate += 2;
    }
}

