@Override public String readString() throws IOException {
    // Read a 4-byte length prefix (big-endian) and then the string bytes
    int b1 = in.read();
    if (b1 == -1) throw new EOFException();
    int b2 = in.read();
    if (b2 == -1) throw new EOFException();
    int b3 = in.read();
    if (b3 == -1) throw new EOFException();
    int b4 = in.read();
    if (b4 == -1) throw new EOFException();
    int length = (b1 << 24) | (b2 << 16) | (b3 << 8) | b4;
    if (length < 0) throw new IOException("Invalid string length: " + length);
    byte[] bytes = new byte[length];
    int offset = 0;
    while (offset < length) {
        int read = in.read(bytes, offset, length - offset);
        if (read == -1) throw new EOFException();
        offset += read;
    }
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
}

