private java.util.Map<java.lang.String,java.lang.Object> buildContent(com.google.gson.JsonObject jsonObject){
    java.util.Map<java.lang.String,java.lang.Object> map = new java.util.HashMap<>();
    if (jsonObject==null){
        return map;
    }
    for (java.util.Map.Entry<java.lang.String,com.google.gson.JsonElement> entry : jsonObject.entrySet()){
        java.lang.String key = entry.getKey();
        com.google.gson.JsonElement element = entry.getValue();
        java.lang.Object value = null;
        if (element==null || element.isJsonNull()){
            value = null;
        } else if (element.isJsonPrimitive()){
            com.google.gson.JsonPrimitive prim = element.getAsJsonPrimitive();
            if (prim.isBoolean()){
                value = prim.getAsBoolean();
            } else if (prim.isNumber()){
                java.lang.Number num = prim.getAsNumber();
                if (num.doubleValue()==num.longValue()){
                    if (num.longValue() <= java.lang.Integer.MAX_VALUE && num.longValue() >= java.lang.Integer.MIN_VALUE){
                        value = java.lang.Integer.valueOf(num.intValue());
                    } else {
                        value = java.lang.Long.valueOf(num.longValue());
                    }
                } else {
                    value = java.lang.Double.valueOf(num.doubleValue());
                }
            } else if (prim.isString()){
                value = prim.getAsString();
            }
        } else if (element.isJsonObject()){
            value = buildContent(element.getAsJsonObject());
        } else if (element.isJsonArray()){
            java.util.List<java.lang.Object> list = new java.util.ArrayList<>();
            for (com.google.gson.JsonElement arrElem : element.getAsJsonArray()){
                if (arrElem.isJsonPrimitive()){
                    com.google.gson.JsonPrimitive prim = arrElem.getAsJsonPrimitive();
                    if (prim.isBoolean()){
                        list.add(prim.getAsBoolean());
                    } else if (prim.isNumber()){
                        java.lang.Number num = prim.getAsNumber();
                        if (num.doubleValue()==num.longValue()){
                            if (num.longValue() <= java.lang.Integer.MAX_VALUE && num.longValue() >= java.lang.Integer.MIN_VALUE){
                                list.add(java.lang.Integer.valueOf(num.intValue()));
                            } else {
                                list.add(java.lang.Long.valueOf(num.longValue()));
                            }
                        } else {
                            list.add(java.lang.Double.valueOf(num.doubleValue()));
                        }
                    } else {
                        list.add(prim.getAsString());
                    }
                } else if (arrElem.isJsonObject()){
                    list.add(buildContent(arrElem.getAsJsonObject()));
                } else {
                    list.add(null);
                }
            }
            value = list;
        }
        map.put(key,value);
    }
    if (jsonObject.has("ats") && !jsonObject.get("ats").isJsonNull()){
        map.put("ats",jsonObject.get("ats"));
    }
    return map;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()){
        String key = entry.getKey();
        JsonElement element = entry.getValue();
        if (element.isJsonPrimitive()){
            content.put(key, element.getAsJsonPrimitive());
        } else if (element.isJsonArray()){
            List<Object> list = new ArrayList<>();
            for (JsonElement e : element.getAsJsonArray()){
                if (e.isJsonPrimitive()){
                    list.add(e.getAsJsonPrimitive());
                } else if (e.isJsonObject()){
                    list.add(buildContent(e.getAsJsonObject()));
                } else {
                    list.add(e);
                }
            }
            content.put(key, list);
        } else if (element.isJsonObject()){
            content.put(key, buildContent(element.getAsJsonObject()));
        } else {
            content.put(key, null);
        }
    }
    return content;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> content = new HashMap<>();
    if (jsonObject == null) {
        return content;
    }
    // iterate over all properties in the JsonObject
    for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
        String key = entry.getKey();
        JsonElement element = entry.getValue();
        // convert JsonElement to its corresponding Java object
        if (element.isJsonPrimitive()) {
            JsonPrimitive prim = element.getAsJsonPrimitive();
            if (prim.isNumber()) {
                content.put(key, prim.getAsNumber());
            } else if (prim.isBoolean()) {
                content.put(key, prim.getAsBoolean());
            } else if (prim.isString()) {
                content.put(key, prim.getAsString());
            } else {
                content.put(key, prim.toString());
            }
        } else if (element.isJsonObject()) {
            // recurse into nested objects
            content.put(key, buildContent(element.getAsJsonObject()));
        } else if (element.isJsonArray()) {
            // convert array to List<Object>
            List<Object> list = new ArrayList<>();
            for (JsonElement e : element.getAsJsonArray()) {
                if (e.isJsonPrimitive()) {
                    JsonPrimitive prim = e.getAsJsonPrimitive();
                    if (prim.isNumber()) list.add(prim.getAsNumber());
                    else if (prim.isBoolean()) list.add(prim.getAsBoolean());
                    else if (prim.isString()) list.add(prim.getAsString());
                    else list.add(prim.toString());
                } else if (e.isJsonObject()) {
                    list.add(buildContent(e.getAsJsonObject()));
                } else if (e.isJsonArray()) {
                    list.add(e.getAsJsonArray()); // keep raw JsonArray if nested
                } else {
                    list.add(e.toString());
                }
            }
            content.put(key, list);
        } else if (element.isJsonNull()) {
            content.put(key, null);
        }
    }
    // if the map or jsonObject contains an "ats" field we keep it (already added above)
    return content;
}

private Map<String,Object> buildContent(JsonObject jsonObject){
    Map<String,Object> result = new HashMap<>();
    if(jsonObject == null){
        return result;
    }
    for(Map.Entry<String, JsonElement> entry : jsonObject.entrySet()){
        result.put(entry.getKey(), entry.getValue());
    }
    if(jsonObject.has("ats")){
        result.put("ats", jsonObject.get("ats"));
    }
    return result;
}

