public final byte[] toByteArray() {
    if (mWriter == null) {
        return new byte[0];
    }
    if (mWriter.hasArray()) {
        byte[] array = mWriter.array();
        int offset = mWriter.arrayOffset();
        int len = mWriter.position();
        return java.util.Arrays.copyOfRange(array, offset, offset + len);
    } else {
        mWriter.mark();
        byte[] result = new byte[mWriter.remaining()];
        mWriter.get(result);
        mWriter.reset();
        return result;
    }
}

