public final byte[] toByteArray(){
    // If no buffers are available, return an empty array
    if (buffers == null || buffers.length == 0) {
        return new byte[0];
    }
    try {
        // Combine all individual buffers into a single output stream
        ByteArrayOutputStream combined = new ByteArrayOutputStream();
        for (ByteArrayOutputStream buf : buffers) {
            if (buf != null) {
                combined.write(buf.toByteArray());
            }
        }
        return combined.toByteArray();
    } catch (IOException e) {
        // In the event of an unexpected write error, fall back to an empty array
        return new byte[0];
    }
}

