        if (pos >= bufLen) {
            throw new IndexOutOfBoundsException("Unexpected end of classFileBuffer while skipping entries");
        }
        int tag = buf[pos++] & 0xFF;
        switch (tag) {
            case 1: { // CONSTANT_Utf8
                if (pos + 2 > bufLen) {
                    throw new IndexOutOfBoundsException("Malformed constant pool entry: insufficient length field");
                }
                int len = ((buf[pos] & 0xFF) << 8) | (buf[pos + 1] & 0xFF);
                pos += 2 + len;
                break;
            }
            case 3: case 4: case 7: case 8: case 9: case 10: case 11: case 12: { // 2-byte values
                pos += 2;
                break;
            }
            case 5: case 6: { // 8-byte values consume two indices
                pos += 8;
                index++; // skip the additional index
                break;
            }
            default:
                throw new IllegalStateException("Unknown constant pool tag encountered: " + tag);
        }
        index++;
    }
    // Now at the desired entry
    if (pos >= bufLen) {
        throw new IndexOutOfBoundsException("Reached end of buffer before reading target entry");
    }
    int tag = buf[pos++] & 0xFF;
    if (tag != 1) {
        throw new IllegalArgumentException("Constant pool entry at index " + constantPoolEntryIndex + " is not a CONSTANT_Utf8");
    }
    if (pos + 2 > bufLen) {
        throw new IndexOutOfBoundsException("Malformed UTF8 entry: missing length");
    }
    int len = ((buf[pos] & 0xFF) << 8) | (buf[pos + 1] & 0xFF);
    pos += 2;
    if (pos + len > bufLen) {
        throw new IndexOutOfBoundsException("Malformed UTF8 entry: insufficient byte data");
    }
    if (charBuffer.length < len) {
        throw new IllegalArgumentException("Provided charBuffer too small for UTF8 string of length " + len);
    }
    String utfString = new String(buf, pos, len, java.nio.charset.StandardCharsets.UTF_8);
    // Copy the string into the provided char buffer
    char[] temp = utfString.toCharArray();
    System.arraycopy(temp, 0, charBuffer, 0, len);
    return utfString;
