private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("predicate cannot be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node cannot be null");
    }
    // Construct a circulator starting at 'start' and in the given direction.
    OuterFaceCirculator circ;
    try {
        circ = new OuterFaceCirculator(start, dir);
    } catch (Exception e) {
        throw new IllegalStateException("Failed to create circulator", e);
    }

    // Walk until the predicate is satisfied or the stop node is reached.
    while (true) {
        Node current = circ.node();
        if (current == null) {
            break; // safety guard against infinite loop
        }
        if (predicate.test(current) || current.equals(stop)) {
            break;
        }
        // Advance in the specified direction
        if (dir > 0) {
            circ = circ.next();
        } else {
            circ = circ.prev();
        }
    }
    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop nodes must not be null");
    }

    // Create a circulator starting at `start` in the given direction.
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the start node itself satisfies the predicate or is the stop node,
    // no traversal is needed.
    if (predicate.test(circ.node()) || circ.node().equals(stop)) {
        return circ;
    }

    try {
        while (!circ.node().equals(stop)) {
            circ.advance();               // Move to the next node in the specified direction.
            Node current = circ.node();
            if (predicate.test(current)) {
                return circ;               // Desired node found.
            }
            // If we loop back to start without finding the predicate,
            // it means the component does not contain a matching node.
            if (current.equals(start)) {
                break;
            }
        }
    } catch (Exception e) {
        // Any unexpected runtime issues are treated as a failure to find a match.
        // In this case we simply return the circulator pointing at the stop node.
    }

    // Either the stop node was reached or we had an intervening exception.
    // Ensure the circulator points exactly at the stop node.
    while (!circ.node().equals(stop)) {
        circ.advance();
    }

    return circ;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("start and stop must not be null");
    }
    // Create a circulator starting at the provided node and direction
    OuterFaceCirculator cir = new OuterFaceCirculator(start, dir);
    // If the starting node already satisfies the predicate, return it
    if (predicate.test(start)) {
        return cir;
    }
    Node current = start;
    // Walk the boundary until we hit the stop node or find a node that satisfies the predicate
    do {
        // Advance the circulator (assumes next() moves to the next node on the outer face)
        cir.next();
        current = cir.getCurrent(); // retrieve the node the circulator is pointing at
        if (predicate.test(current)) {
            return cir;
        }
    } while (!current.equals(stop) && !current.equals(start));
    // If we exited because we reached the stop node, return circulator at stop
    if (!current.equals(stop)) {
        // In the unlikely event we looped back to start without hitting stop,
        // fall back to creating a new circulator that starts at the stop node.
        cir = new OuterFaceCirculator(stop, dir);
    }
    return cir;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop must not be null");
    }
    Node current = start;
    while (true) {
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
        if (current.equals(stop)) {
            return new OuterFaceCirculator(stop);
        }
        current = current.getNextOnOuterFace(dir);
        if (current == null) {
            return new OuterFaceCirculator(stop);
        }
    }
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Arguments must not be null");
    }
    Node current = start;
    if (predicate.test(current)) {
        return new OuterFaceCirculator(current);
    }
    while (!current.equals(stop)) {
        current = current.next(dir); // advance in the specified direction
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
    }
    return new OuterFaceCirculator(stop);
}

