        java.lang.reflect.Field[] fields = clazz.getDeclaredFields();
        java.util.Map<Integer, java.lang.reflect.Field> indexMap = new java.util.HashMap<>();
        for (java.lang.reflect.Field field : fields) {
            ShardingKey sk = field.getAnnotation(ShardingKey.class);
            if (sk != null) {
                int index = sk.index();
