        if (indexMap.isEmpty()) {
            return; // no sharding keys to check
        }
        int maxIndex = java.util.Collections.max(indexMap.keySet());
        for (int i = 0; i <= maxIndex; i++) {
            if (!indexMap.containsKey(i)) {
                throw new IllegalStateException(
                    "Sharding key indices are not continuous. Missing index: " + i);
            }
        }
    } catch (ClassNotFoundException e) {
        throw new IllegalStateException("Model class not found: " + modelName, e);
    } catch (Exception e) {
        throw new IllegalStateException("Error checking sharding keys for model: " + modelName, e);
    }
}

