    // Without concrete API details, we return null to indicate that a proper conversion
    // cannot be performed in this generic context.
    return null;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (graph == null || tour == null) {
        return null;
    }
    if (tour.isEmpty()) {
        // Empty path
        return new GraphWalk<>(graph, null, null, new ArrayList<V>(), new ArrayList<E>());
    }
    // Map each vertex to the list of incident edges in the tour
    Map<V, List<E>> vertexEdges = new HashMap<>();
    for (E e : tour) {
        V src = graph.getEdgeSource(e);
        V tgt = graph.getEdgeTarget(e);
        vertexEdges.computeIfAbsent(src, k -> new ArrayList<E>()).add(e);
        if (!graph.isDirected()) {
            vertexEdges.computeIfAbsent(tgt, k -> new ArrayList<E>()).add(e);
        } else {
            // For directed graphs we store only the outgoing adjacency for traversal
            vertexEdges.computeIfAbsent(tgt, k -> new ArrayList<E>()).add(e);
        }
    }
    // Choose a starting vertex: pick source of the first edge in the set
    Iterator<E> it = tour.iterator();
    if (!it.hasNext()) {
        return new GraphWalk<>(graph, null, null, new ArrayList<V>(), new ArrayList<E>());
    }
    E startEdge = it.next();
    V startVertex = graph.getEdgeSource(startEdge);
    V current = startVertex;
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    while (!remaining.isEmpty()) {
        E nextEdge = null;
        List<E> adj = vertexEdges.getOrDefault(current, Collections.emptyList());
        for (E e : adj) {
            if (!remaining.contains(e)) {
                continue;
            }
            // For directed graphs ensure the edge is outgoing from current
            if (graph.isDirected()) {
                if (!graph.getEdgeSource(e).equals(current)) {
                    continue;
                }
            }
            nextEdge = e;
            break;
        }
        if (nextEdge == null) {
            // Tour not properly connected
            break;
        }
        // Add vertex at the beginning of the path
        if (vertexList.isEmpty() || !vertexList.get(vertexList.size() - 1).equals(current)) {
            vertexList.add(current);
        }
        edgeList.add(nextEdge);
        remaining.remove(nextEdge);
        // Determine the next vertex
        V src = graph.getEdgeSource(nextEdge);
        V tgt = graph.getEdgeTarget(nextEdge);
        current = src.equals(current) ? tgt : src;
    }
    // Add the last vertex of the path
    vertexList.add(current);
    return new GraphWalk<>(graph, vertexList.get(0), current, vertexList, edgeList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour,Graph<V,E> graph){
    try {
        if (tour == null || tour.isEmpty()) return null;
        // Build adjacency map of vertices to incident edges
        Map<V, List<E>> adj = new HashMap<>();
        for (E e : tour) {
            V source = graph.getEdgeSource(e);
            V target = graph.getEdgeTarget(e);
            adj.computeIfAbsent(source, k -> new ArrayList<>()).add(e);
            if (!graph.getType().isDirected()) {
                adj.computeIfAbsent(target, k -> new ArrayList<>()).add(e);
            }
        }
        // Find a start vertex (prefer one with degree 1 if possible)
        V start = null;
        for (Map.Entry<V, List<E>> entry : adj.entrySet()) {
            if (entry.getValue().size() == 1) {
                start = entry.getKey();
                break;
            }
        }
        if (start == null && !adj.isEmpty()) {
            start = adj.keySet().iterator().next();
        }
        if (start == null) return null;
        // Traverse to build the ordered path
        List<V> vertices = new ArrayList<>();
        List<E> edges = new ArrayList<>();
        vertices.add(start);
        V current = start;
        E prevEdge = null;
        Set<E> remaining = new HashSet<>(tour);
        while (!remaining.isEmpty()) {
            List<E> candidates = adj.get(current);
            if (candidates == null) break;
            E nextEdge = null;
            for (E e : candidates) {
                if (!remaining.contains(e)) continue;
                if (e.equals(prevEdge)) continue;
                nextEdge = e;
                break;
            }
            if (nextEdge == null) break;
            edges.add(nextEdge);
            remaining.remove(nextEdge);
            V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                    ? graph.getEdgeTarget(nextEdge)
                    : graph.getEdgeSource(nextEdge);
            vertices.add(nextVertex);
            prevEdge = nextEdge;
            current = nextVertex;
        }
        return new org.jgrapht.graph.DefaultGraphPath<>(graph, vertices, edges);
    } catch (Exception ex) {
        return null;
    }
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (graph == null || tour == null) {
        throw new IllegalArgumentException("graph and tour must not be null");
    }
    if (tour.isEmpty()) {
        return new DefaultGraphPath<>(graph, null, null, Collections.emptyList(), 0.0);
    }
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge not part of graph: " + e);
        }
    }

    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }

    E firstEdge = tour.iterator().next();
    V startVertex = graph.getEdgeSource(firstEdge);
    V current = startVertex;
    List<E> path = new ArrayList<>(tour.size());
    Set<E> remaining = new HashSet<>(tour);

    while (!remaining.isEmpty()) {
        List<E> possible = adjacency.getOrDefault(current, Collections.emptyList());
        E chosen = null;
        for (E e : possible) {
            if (remaining.contains(e)) {
                chosen = e;
                break;
            }
        }
        if (chosen == null) {
            throw new IllegalArgumentException("Unable to construct a path from the provided edge set.");
        }
        path.add(chosen);
        remaining.remove(chosen);
        V src = graph.getEdgeSource(chosen);
        V tgt = graph.getEdgeTarget(chosen);
        current = current.equals(src) ? tgt : src;
    }

    V targetVertex;
    if (path.isEmpty()) {
        targetVertex = startVertex;
    } else {
        targetVertex = graph.getEdgeTarget(path.get(path.size() - 1));
        if (targetVertex.equals(startVertex)) {
            targetVertex = startVertex;
        }
    }

    double weight = 0.0;
    for (E e : path) {
        weight += graph.getEdgeWeight(e);
    }

    return new DefaultGraphPath<>(graph, startVertex, targetVertex, path, weight);
}

