int addConstantNameAndType(final String name, final String descriptor) { 
    if (name == null || descriptor == null) { 
        throw new IllegalArgumentException("name and descriptor must not be null"); 
    } 
    try { 
        int nameIndex = findUtf8(name); 
        int descIndex = findUtf8(descriptor); 
        if (nameIndex == NOT_FOUND || descIndex == NOT_FOUND) { 
            throw new IllegalStateException("UTF8 strings not found in constant pool"); 
        } 
        int existing = findNameAndType(nameIndex, descIndex); 
        if (existing != NOT_FOUND) { 
            return existing; 
        } 
