    if (bucketsByLabel == null || labels == null) {
        throw new IllegalArgumentException("bucketsByLabel and labels must not be null");
    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("minLabel out of bounds");
    }
    if (minLabel == 0) {
        return; // nothing to move
    }

    Set<Integer> sourceSet = bucketsByLabel.get(minLabel);
    if (sourceSet == null || sourceSet.isEmpty()) {
        return;
    }

    Set<Integer> targetSet = bucketsByLabel.get(0);
    if (targetSet == null) {
        targetSet = new HashSet<>();
        bucketsByLabel.set(0, targetSet);
    }

    for (Integer vertex : sourceSet) {
        if (vertex < 0 || vertex >= labels.size()) {
            throw new IllegalArgumentException("vertex index out of bounds in labels list");
        }
        labels.set(vertex, 0);
    }

    targetSet.addAll(sourceSet);
    sourceSet.clear();
}

