public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    int lastSepIndex = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int lastDotIndex = path.lastIndexOf('.');
    if (lastDotIndex == -1 || lastDotIndex <= lastSepIndex || lastDotIndex == path.length() - 1) {
        return null;
    }
    return path.substring(0, lastDotIndex);
}

public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    int lastUnixSep = path.lastIndexOf('/');
    int lastWindowsSep = path.lastIndexOf('\\');
    int lastSeparator = Math.max(lastUnixSep, lastWindowsSep);
    int lastDot = path.lastIndexOf('.');
    if (lastDot > lastSeparator) {
        return path.substring(0, lastDot);
    }
    return path;
}

public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    // Find position of last file separator (handle both '/' and '\\')
    int lastSep = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // Find last dot in the path
    int lastDot = path.lastIndexOf('.');
    // If there is a dot after the last separator, strip extension
    if (lastDot > lastSep) {
        return path.substring(0, lastDot);
    }
    // No extension found; return the original path unchanged
    return path;
}

public static String stripFilenameExtension(String path){
    if (path == null) {
        return null;
    }
    // Find the position of the last directory separator (either '/' or '\\').
    int lastSeparator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // Find the position of the last dot in the path.
    int lastDot = path.lastIndexOf('.');
    // If a dot exists after the last separator and it is not the very first character, it denotes an extension.
    if (lastDot > lastSeparator && lastDot != 0) {
        return path.substring(0, lastDot);
    }
    return path;
}

public static String stripFilenameExtension(String path){
    if (path == null) return null;
    int lastSeparator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    int lastDot = path.lastIndexOf('.');
    if (lastDot <= lastSeparator + 1) return null;
    return path.substring(0, lastDot);
}

