private void moveAllListNodes(DoublyLinkedList<E> list){
    if (list == null) {
        throw new IllegalArgumentException("list cannot be null");
    }
    if (list.head == null) {
        return;
    }
    if (this.head == null) {
        this.head = list.head;
        this.tail = list.tail;
    } else {
        this.tail.next = list.head;
        list.head.prev = this.tail;
        this.tail = list.tail;
    }
    this.elementCount += list.elementCount;
    list.elementCount = 0;
    list.head = null;
    list.tail = null;
}

