        java.lang.reflect.Method getTargetSource = map.getClass().getMethod("getTarget");
        sourceBean = getTargetSource.invoke(map);
    } catch (Exception e) {
        try {
            java.lang.reflect.Method getBeanSource = map.getClass().getMethod("getBean");
            sourceBean = getBeanSource.invoke(map);
        } catch (Exception ex) {
            return; // Cannot retrieve source bean, abort
        }
    }
    try {
        // Try to obtain the underlying bean from the target map (this)
        java.lang.reflect.Method getTargetTarget = this.getClass().getMethod("getTarget");
        targetBean = getTargetTarget.invoke(this);
    } catch (Exception e) {
        try {
            java.lang.reflect.Method getBeanTarget = this.getClass().getMethod("getBean");
            targetBean = getBeanTarget.invoke(this);
        } catch (Exception ex) {
            return; // Cannot retrieve target bean, abort
        }
    }
    try {
        java.beans.BeanInfo sourceInfo = java.beans.Introspector.getBeanInfo(sourceBean.getClass(), Object.class);
        java.beans.BeanInfo targetInfo = java.beans.Introspector.getBeanInfo(targetBean.getClass(), Object.class);
        java.util.Map<String, java.beans.PropertyDescriptor> sourceProps = new java.util.HashMap<>();
        for (java.beans.PropertyDescriptor pd : sourceInfo.getPropertyDescriptors()) {
            sourceProps.put(pd.getName(), pd);
        }
        for (java.beans.PropertyDescriptor tgtPd : targetInfo.getPropertyDescriptors()) {
            java.beans.PropertyDescriptor srcPd = sourceProps.get(tgtPd.getName());
            if (srcPd == null) {
                continue;
