            java.lang.reflect.Method readMethod = srcPd.getReadMethod();
            java.lang.reflect.Method writeMethod = tgtPd.getWriteMethod();
            if (readMethod != null && writeMethod != null) {
                try {
                    Object value = readMethod.invoke(sourceBean);
                    writeMethod.invoke(targetBean, value);
                } catch (Exception e) {
                    // Skip property if any exception occurs (e.g., read-only, write-only, etc.)
                }
            }
        }
    } catch (Exception e) {
        // If any introspection or reflection error occurs, silently ignore
    }
