    boolean startOfWord = true;
    for (int i = 0; i < remaining.length(); i++) {
        char c = remaining.charAt(i);
        if (Character.isWhitespace(c)) {
            startOfWord = true;
        } else {
            if (startOfWord) {
                buf.append(c);
                startOfWord = false;
            }
        }
    }
