    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (nameStart < 0 || nameStart > buf.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }
    try {
        StringBuilder abbr = new StringBuilder();
        boolean atWordStart = true;
        int i = nameStart;
        while (i < buf.length()) {
            char c = buf.charAt(i);
            if (Character.isWhitespace(c)) {
                atWordStart = true;
            } else {
                if (atWordStart) {
                    abbr.append(Character.toUpperCase(c));
                    abbr.append('.');
                    atWordStart = false;
                }
            }
            i++;
        }
        buf.delete(nameStart, buf.length());
        buf.insert(nameStart, abbr);
    } catch (Exception e) {
        // Preserve original buffer content on error
        throw new RuntimeException("Failed to abbreviate name", e);
    }
}

