private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>(keys.size());
    TreeSet<Integer> sorted = new TreeSet<>();
    for (K k : keys) {
        try {
            Integer val = (Integer) k;
            sorted.add(val);
        } catch (ClassCastException e) {
            // Key is not an Integer; ignore for sorting
        }
    }
    for (K k : keys) {
        try {
            Integer val = (Integer) k;
            Integer lower = sorted.lower(val);
            bounds.add(lower != null ? lower : Integer.MIN_VALUE);
        } catch (ClassCastException e) {
            bounds.add(null);
        }
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    // Iterate over each key to determine its maximum lower bound
    for (int i = 0; i < keys.size(); i++) {
        Integer maxBound = null;
        K currentKey = keys.get(i);
        // Compare against all previous keys
        for (int j = 0; j < i; j++) {
            K potentialBound = keys.get(j);
            try {
                // Attempt natural ordering comparison
                @SuppressWarnings("unchecked")
                Comparable<K> comp = (Comparable<K>) potentialBound;
                if (comp.compareTo(currentKey) <= 0) {
                    Integer potentialInt = convertToInt(potentialBound);
                    if (potentialInt != null && (maxBound == null || potentialInt > maxBound)) {
                        maxBound = potentialInt;
                    }
                }
            } catch (ClassCastException | ClassNotFoundException e) {
                // If not comparable, ignore this potential bound
                continue;
            }
        }
        // If no valid lower bound found, use a sentinel value (e.g., Integer.MIN_VALUE)
        lowerBounds.add(maxBound != null ? maxBound : Integer.MIN_VALUE);
    }
    return lowerBounds;
}

