private void pop(final String descriptor){
    int count = 0;
    if (descriptor == null || descriptor.isEmpty()){
        return;
    }
    if (descriptor.charAt(0) == '('){ // method descriptor: pop argument types
        int i = 1;
        while (i < descriptor.length() && descriptor.charAt(i) != ')'){
            // skip array brackets
            while (descriptor.charAt(i) == '['){
                i++;
            }
            char t = descriptor.charAt(i);
            if (t == 'L'){ // object type
                i++; // skip 'L'
                while (i < descriptor.length() && descriptor.charAt(i) != ';'){
                    i++;
                }
                i++; // skip ';'
                count += 1; // object occupies one slot
            } else { // primitive
                i++; // consume primitive
                if (t == 'J' || t == 'D'){
                    count += 2; // long/double take two slots
                } else {
                    count += 1;
                }
            }
        }
    } else { // single type descriptor
        int i = 0;
        while (i < descriptor.length() && descriptor.charAt(i) == '['){
            i++;
        }
        char t = descriptor.charAt(i);
        if (t == 'L'){ // object
            count += 1;
        } else { // primitive
            if (t == 'J' || t == 'D'){
                count += 2;
            } else {
                count += 1;
            }
        }
    }
    if (count > pos){
        throw new IllegalStateException("Pop exceeds stack height: requested " + count + ", available " + pos);
    }
    pos -= count;
}

