        return false;
    }
    double dx = p1.getX() - p2.getX();
    double dy = p1.getY() - p2.getY();
    double distanceSquared = dx * dx + dy * dy;
    double tolerance = 1e-9;
    double toleranceSquared = tolerance * tolerance;
    return distanceSquared <= toleranceSquared;
}

