public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        return null;
    }
    // Determine the base directory from the given path
    String baseDir;
    int lastSlash = path.lastIndexOf('/');
    if (lastSlash >= 0) {
        baseDir = path.substring(0, lastSlash);
    } else {
        baseDir = "";
    }

    // Use a deque to build the final path components
    java.util.Deque<String> stack = new java.util.ArrayDeque<>();

    // Add base directory components to stack
    if (!baseDir.isEmpty()) {
        String[] baseParts = baseDir.split("/");
        for (String part : baseParts) {
            if (!part.isEmpty()) {
                stack.addLast(part);
            }
        }
    }

    // Process relative path components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.removeLast();
            }
            continue;
        }
        stack.addLast(part);
    }

    // Build the resulting path string
    StringBuilder result = new StringBuilder();
    if (path.startsWith("/")) {
        result.append("/");
    }
    boolean first = true;
    for (String comp : stack) {
        if (!first) {
            result.append("/");
        }
        result.append(comp);
        first = false;
    }

    // Handle case where result is empty after processing
    if (result.length() == 0) {
        return path.startsWith("/") ? "/" : "";
    }

    return result.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    // Validate inputs
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("path and relativePath must not be null");
    }

    boolean absolute = path.startsWith("/");
    java.util.List<String> stack = new java.util.ArrayList<>();

    // Process base path components
    for (String part : path.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            } else if (!absolute) {
                // if base is relative and we cannot pop, keep the '..'
                stack.add("..");
            }
        } else {
            stack.add(part);
        }
    }

    // Process relative path components
    for (String part : relativePath.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            } else if (!absolute) {
                stack.add("..");
            }
        } else {
            stack.add(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (absolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }

    // Handle the case where nothing remains
    if (result.length() == 0) {
        return absolute ? "/" : ".";
    }
    return result.toString();
}

