public int readTag() throws IOException {
    int result = 0;
    for (int shift = 0; shift < 32; shift += 7) {
        int b = in.read();
        if (b == -1) {
            return 0; // EOF
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
    }
    throw new IOException("Malformed varint");
}

