        java.lang.reflect.Field fTotal = this.getClass().getDeclaredField("total");
        fStart.setAccessible(true);
        fEnd.setAccessible(true);
        fTotal.setAccessible(true);
        Object oStart = fStart.get(this);
        Object oEnd = fEnd.get(this);
        Object oTotal = fTotal.get(this);
        if(oStart instanceof Number && oEnd instanceof Number && oTotal instanceof Number){
            start = ((Number)oStart).intValue();
            end = ((Number)oEnd).intValue();
            total = ((Number)oTotal).longValue();
        }
    } catch (Exception ignored) {
    }
    if(start != null && end != null && total != null){
        return "bytes " + start + "-" + end + "/" + total;
    }
    return null;
}

