        line = line.trim();
        if (line.isEmpty()) {
            continue;
        }
        ThreadSnapshot ts;
        try {
            ts = ThreadSnapshot.parse(line);
        } catch (Exception e) {
            // ignore malformed lines
            continue;
        }
        if (ts == null) {
            continue;
        }
        if (timeRanges == null || timeRanges.isEmpty()) {
            snapshots.add(ts);
            continue;
        }
        long tsTime = ts.getTimestamp();
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (range == null) {
                continue;
            }
            long start = range.getStart();
            long end = range.getEnd();
            if (tsTime >= start && tsTime <= end) {
                snapshots.add(ts);
                break;
            }
        }
    }
    reader.close();
    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            try {
                ThreadSnapshot snapshot = ThreadSnapshot.fromString(line);
                result.add(snapshot);
            } catch (Exception e) {
                // Skip malformed line
            }
        }
    }

    List<ThreadSnapshot> filtered = new ArrayList<>();
    for (ThreadSnapshot ts : result) {
        long tsTime = ts.getTimestamp();
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (tsTime >= range.getStartTime() && tsTime <= range.getEndTime()) {
                filtered.add(ts);
                break;
            }
        }
    }
    return filtered;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IOException("File is null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IOException("File does not exist or is not a regular file: " + file);
    }
    List<ThreadSnapshot> allSnapshots;
    try {
        allSnapshots = ThreadSnapshot.parseList(file);
    } catch (Exception e) {
        throw new IOException("Failed to parse thread snapshots from file: " + file, e);
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return allSnapshots;
    }
    List<ThreadSnapshot> result = new ArrayList<>();
    for (ThreadSnapshot snapshot : allSnapshots) {
        if (snapshot == null) {
            continue;
        }
        long ts;
        try {
            ts = snapshot.getTimestamp(); // assume ThreadSnapshot has this method
        } catch (Exception e) {
            // Skip snapshots that cannot provide a timestamp
            continue;
        }
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (range == null) {
                continue;
            }
            long start, end;
            try {
                start = range.getStartMillis(); // assume ProfileAnalyzeTimeRange has this method
                end = range.getEndMillis();     // assume ProfileAnalyzeTimeRange has this method
            } catch (Exception e) {
                // Skip ranges that cannot provide bounds
                continue;
            }
            if (ts >= start && ts <= end) {
                result.add(snapshot);
                break;
            }
        }
    }
    return result;
}
